const { parseTime, formatMinutes, parseRange } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen = 0) {
  const start = parseTime(dayStart);
  const end = parseTime(dayEnd);
  if (end <= start) {
    throw new Error("dayEnd must be after dayStart");
  }

  const clipped = [];
  for (const item of busy) {
    const r = parseRange(item);
    const s = Math.max(r.start, start);
    const e = Math.min(r.end, end);
    if (e > s) {
      clipped.push({ start: s, end: e });
    }
  }

  clipped.sort((a, b) => a.start - b.start || a.end - b.end);

  const slots = [];
  let cursor = start;

  for (const r of clipped) {
    if (r.start > cursor && r.start - cursor >= minLen) {
      slots.push(`${formatMinutes(cursor)}-${formatMinutes(r.start)}`);
    }
    if (r.end > cursor) {
      cursor = r.end;
    }
  }

  if (end > cursor && end - cursor >= minLen) {
    slots.push(`${formatMinutes(cursor)}-${formatMinutes(end)}`);
  }

  return slots;
}

module.exports = { freeSlots };
