// Splits a bill (in agorot, a whole number) between people by weights.
function toDecimalBigInt(x) {
  const [coeff, expPart] = String(x).toLowerCase().split("e");
  const exp = expPart ? parseInt(expPart, 10) : 0;
  const [intPart, fracPart = ""] = coeff.split(".");
  return { mantissa: BigInt(intPart + fracPart), exp: exp - fracPart.length };
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => !(w > 0) || !Number.isFinite(w))) {
    throw new Error("bad weights");
  }

  const parsed = weights.map(toDecimalBigInt);
  const minExp = Math.min(...parsed.map((p) => p.exp));
  const scaled = parsed.map((p) => p.mantissa * 10n ** BigInt(p.exp - minExp));
  const sum = scaled.reduce((a, b) => a + b, 0n);
  const totalBig = BigInt(total);

  const shares = [];
  const remainders = [];
  let assigned = 0n;

  for (let i = 0; i < scaled.length; i++) {
    const numerator = totalBig * scaled[i];
    const floor = numerator / sum;
    shares.push(Number(floor));
    remainders.push(numerator % sum);
    assigned += floor;
  }

  const leftover = Number(totalBig - assigned);
  const order = scaled.map((_, i) => i).sort((a, b) => {
    if (remainders[b] > remainders[a]) return 1;
    if (remainders[b] < remainders[a]) return -1;
    return a - b;
  });

  for (let i = 0; i < leftover; i++) {
    shares[order[i]] += 1;
  }

  return shares;
}

module.exports = { splitBill };
